using System;using System.IO;using System.Linq;using Newtonsoft.Json.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class ConRoiR41Survey {
 const string Out="Docs/Reviews/journey_v48/r41";
 static JArray V(Vector3 v)=>new JArray(v.x,v.y,v.z);
 static string P(Transform t)=>t.parent?P(t.parent)+"/"+t.name:t.name;
 public static void Run(){Directory.CreateDirectory(Out);var scenes=new JArray();foreach(var path in new[]{ConRoiR39.Scene,ConRoiR40.Scene}){
  EditorSceneManager.OpenScene(path);var s=UnityEngine.Object.FindAnyObjectByType<DieuPhoiHanhTrinh>();var c=s.slopeChapter;
  var all=UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();
  scenes.Add(new JObject{["scene"]=path,["spawn"]=V(c.spawn.position),["suitcase"]=P(c.suitcase),["casePosition"]=V(c.suitcase.position),["caseRotation"]=V(c.suitcase.eulerAngles),["caseBounds"]=new JArray(c.suitcase.GetComponentsInChildren<Renderer>(true).Select(r=>new JObject{["path"]=P(r.transform),["min"]=V(r.bounds.min),["max"]=V(r.bounds.max)})),["ghost"]=V(c.ghost.position),["finalPuppet"]=V(c.puppet.transform.position),["interactions"]=new JArray(c.environment.GetComponentsInChildren<TuongTacDocV39>(true).Select(i=>new JObject{["path"]=P(i.transform),["pos"]=V(i.transform.position),["finalDoor"]=i.finalDoor,["memoryIndex"]=i.memoryIndex,["text"]=i.memory})),["nearby"]=new JArray(all.Where(t=>t.GetComponent<Renderer>()&&Vector3.Distance(t.GetComponent<Renderer>().bounds.center,c.suitcase.position)<4).Select(t=>new JObject{["path"]=P(t),["min"]=V(t.GetComponent<Renderer>().bounds.min),["max"]=V(t.GetComponent<Renderer>().bounds.max)})),["flowers"]=new JArray(all.Where(t=>t.GetComponent<Renderer>()&&(t.name.ToLower().Contains("flower")||t.name.ToLower().Contains("bougain")||t.name.ToLower().Contains("hoa"))).Select(t=>new JObject{["path"]=P(t),["pos"]=V(t.position),["scale"]=V(t.lossyScale),["rotation"]=V(t.eulerAngles),["active"]=t.gameObject.activeSelf,["enabled"]=t.GetComponent<Renderer>().enabled,["mesh"]=t.GetComponent<MeshFilter>()?AssetDatabase.GetAssetPath(t.GetComponent<MeshFilter>().sharedMesh):"",["materials"]=new JArray(t.GetComponent<Renderer>().sharedMaterials.Select(m=>m?AssetDatabase.GetAssetPath(m):"NULL"))}))});
 }File.WriteAllText(Out+"/source-survey.json",scenes.ToString());EditorApplication.Exit(0);}
}
